package com.greenlink.model;
import java.time.Instant; import org.bson.types.ObjectId; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.CompoundIndex; import org.springframework.data.mongodb.core.mapping.Document;
@Document("ratings") @CompoundIndex(name="user_1_request_1", def="{'user':1,'request':1}", unique=true) public class Rating { @Id private ObjectId id; private ObjectId provider; private ObjectId user; private ObjectId request; private int rating; private String comment=""; @CreatedDate private Instant createdAt; @LastModifiedDate private Instant updatedAt;
public ObjectId getId(){return id;} public void setId(ObjectId v){id=v;} public ObjectId getProvider(){return provider;} public void setProvider(ObjectId v){provider=v;} public ObjectId getUser(){return user;} public void setUser(ObjectId v){user=v;} public ObjectId getRequest(){return request;} public void setRequest(ObjectId v){request=v;} public int getRating(){return rating;} public void setRating(int v){rating=v;} public String getComment(){return comment;} public void setComment(String v){comment=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;}}
